let currentHubMode='home';function show(mode){const from=currentHubMode;currentHubMode=mode;if(mode!=='readscreen')window.stopReadScreenCapture?.();home.hidden=mode!=='home';chatView.hidden=mode!=='chat';videoReference.hidden=mode!=='video';lessonApp.hidden=mode!=='canvas';if(docsView)docsView.hidden=mode!=='docs';if(readScreenView)readScreenView.hidden=mode!=='readscreen';document.body.dataset.mode=mode;if(mode==='readscreen')window.startNeuraDesktopOverlay?.();if(mode==='video'){if(!videoFrame.src)videoFrame.src=videoOrigin()+'/app/?embed=video&parentOrigin='+encodeURIComponent(location.origin)+'&language='+encodeURIComponent(currentLanguage())+'#/tutor';else sendVideoLanguage()}if(mode==='canvas'){if($('lessonModeLabel'))$('lessonModeLabel').textContent='AI Whiteboard Tutor';if($('lessonTitle'))$('lessonTitle').textContent='Interactive Animated Whiteboard';if($('lessonMeta'))$('lessonMeta').textContent='Progressive SVG vector illustrations drawn and narrated in real time';if($('recordVideoBtn'))$('recordVideoBtn').hidden=true;const bp=document.querySelector('.brand .pill');if(bp)bp.textContent='AI WHITEBOARD';const backDoc=$('dxBackToDoc');if(backDoc)backDoc.hidden=!window._docsParked;applyPreferences()}else if($('dxBackToDoc'))$('dxBackToDoc').hidden=true;if(mode==='chat'){renderMessages();renderRecents();setTimeout(()=>$('groqChatInput').focus(),30)}document.dispatchEvent(new CustomEvent('neura:modechange',{detail:{from,to:mode}}))}
