  document.querySelectorAll('[data-hub-nav]').forEach(b=>b.addEventListener('click',()=>{const section=b.dataset.hubNav;if(section==='history'){show('chat');renderRecents()}else showHomeSection(section)}));
  function readBookmarks(){try{return JSON.parse(localStorage.getItem(BOOKMARKS)||'[]')}catch{return[]}}
  function renderBookmarks(){const host=$('hubBookmarkList');host.replaceChildren();const items=readBookmarks();if(!items.length){const empty=document.createElement('p');empty.className='hub-empty';empty.textContent='No bookmarked lessons yet. Open a visual lesson and choose “Save bookmark” to keep it here.';host.append(empty);return}items.slice().reverse().forEach(item=>{const card=document.createElement('article');card.className='hub-bookmark-card';const title=document.createElement('h2');title.textContent=item.title;const prompt=document.createElement('p');prompt.textContent=item.prompt;const meta=document.createElement('small');meta.textContent=new Date(item.savedAt).toLocaleString();const actions=document.createElement('div');actions.className='hub-bookmark-actions';const open=document.createElement('button');open.textContent='Open prompt';open.onclick=()=>{if(item.mode==='video'){show('video');videoFrame.contentWindow?.postMessage({type:'neuralelearn:open-bookmark',prompt:item.prompt},videoOrigin());return}show('canvas');$('concept').value=item.prompt;$('concept').focus()};const download=document.createElement('button');download.textContent='Download notes';download.onclick=()=>{const a=document.createElement('a'),blob=new Blob([item.notes||('# '+item.title+'\n\n'+item.prompt+'\n')],{type:'text/markdown;charset=utf-8'});a.href=URL.createObjectURL(blob);a.download=(item.title||'lesson').replace(/[^a-z0-9]+/gi,'-').toLowerCase()+'.md';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};const remove=document.createElement('button');remove.textContent='Remove';remove.onclick=()=>{localStorage.setItem(BOOKMARKS,JSON.stringify(readBookmarks().filter(x=>x.id!==item.id)));renderBookmarks()};actions.append(open,download,remove);card.append(title,prompt,meta,actions);host.append(card)})}
