  window.addEventListener('message',e=>{if(e.origin!==videoOrigin()||e.source!==videoFrame.contentWindow||e.data?.type!=='neuralelearn:bookmark-data')return;if(!e.data.prompt){$('videoBookmark').textContent='Ask a topic first';setTimeout(()=>$('videoBookmark').textContent='♧ Save bookmark',1800);return}const entry={id:String(Date.now()),savedAt:new Date().toISOString(),mode:'video',title:e.data.title||e.data.prompt,prompt:e.data.prompt,notes:e.data.notes||''};const items=readBookmarks();items.push(entry);localStorage.setItem(BOOKMARKS,JSON.stringify(items.slice(-100)));$('videoBookmark').textContent='✓ Bookmarked';setTimeout(()=>$('videoBookmark').textContent='♧ Save bookmark',1800)});
