  let queuedReadScreenVideoPrompt='',readScreenVideoPromptSent=false,readScreenVideoFrameReady=false;
  function deliverReadScreenVideoPrompt(){if(!queuedReadScreenVideoPrompt||readScreenVideoPromptSent||!readScreenVideoFrameReady)return;const target=videoFrame.contentWindow;if(!target)return;target.postMessage({type:'neuralelearn:read-screen',prompt:queuedReadScreenVideoPrompt,autoNarrate:true},new URL(videoFrame.src).origin);readScreenVideoPromptSent=true}
  videoFrame.addEventListener('load',()=>{readScreenVideoFrameReady=true;deliverReadScreenVideoPrompt()});
  function continueReadScreenInMode(action){
    const session=action.session||{},mode=action.mode;
    const prompt=`I marked a region on my screen. Please explain it using this learning mode.\n\nMy question: ${session.question||'Explain the marked area.'}\n\nWhat NeuraLearn identified: ${session.explanation||'The marked region was not identified clearly.'}\n\nScreen context: ${session.context||'Use the visible context around the marked area.'}\n\nExplain the selected content clearly and connect it to the surrounding context.`;
    if(mode==='chat'){show('chat');sendMessage(prompt);return}
    if(mode==='canvas'){
      show('canvas');$('concept').value=prompt;
      // Screen Viewer launches a fresh canvas lesson; never inherit a muted
      // canvas state from a previous session for this narrated handoff.
      if(window.wbController){window.wbController.isMuted=false;window.wbController.updateControls?.()}
      if(session.image){
        window._attachedFile={name:'Read Screen selection.jpg',mimeType:'image/jpeg',data:session.image,size:Math.max(0,Math.floor((session.image.length-String(session.image).indexOf(',')-1)*3/4)),source:'read-screen'};
        const badge=$('filePreviewBadge'),image=$('filePreviewImg'),name=$('filePreviewName'),size=$('filePreviewSize'),icon=$('filePreviewIcon');
        if(name)name.textContent=window._attachedFile.name;if(size)size.textContent='(screen capture)';
        if(image){image.src=session.image;image.style.display='inline-block'}if(icon)icon.style.display='none';if(badge)badge.style.display='inline-flex';
      }
      requestAnimationFrame(()=>requestAnimationFrame(()=>{const build=$('generateBtn');if(build&&!build.disabled)build.click()}));return
    }
    if(mode==='video'){
      const clean=value=>String(value||'').replace(/\s+/g,' ').trim();
      const head='Explain the marked area in a clear visual lesson. Selection: ';
      const selected=clean(session.explanation)||'Explain the marked screen content.';
      const context=clean(session.context).slice(0,45),questionText=clean(session.question).slice(0,35);
      const suffix=(context?` Context: ${context}.`:'')+(questionText?` Question: ${questionText}.`:'');
      const selectedBudget=Math.max(0,500-head.length-suffix.length);
      queuedReadScreenVideoPrompt=(head+selected.slice(0,selectedBudget)+suffix).slice(0,500);
      readScreenVideoPromptSent=false;readScreenVideoFrameReady=false;
      const videoUrl=new URL(videoOrigin()+'/app/');videoUrl.searchParams.set('embed','video');videoUrl.searchParams.set('parentOrigin',location.origin);videoUrl.searchParams.set('language',currentLanguage());videoUrl.searchParams.set('readScreenHandoff',String(Date.now()));videoUrl.hash='/tutor';
      videoFrame.src=videoUrl.href;show('video');
    }
  }
